  ]
}

queries/camayoc_falsifiers_not_rerun.jso:
{
  "action": "load",
  "name": "camayoc_falsifiers_not_rerun",
  "description": "verification-and-liveness Q3: 'X is fixed/landed/deployed' claims whose falsifier was last run BEFORE a given change \u2014 stale proofs wearing current ones' clothes. The comparison is read-time: verifiedAt is a fact of the run, and 'still current' is never stored.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?verification ?label ?claim ?verifiedAt WHERE { ?verification a aegis:Verification ; rdfs:label ?label ; aegis:verifies ?claim ; aegis:verifiedAt ?verifiedAt . FILTER(?verifiedAt < \"{changedAt}\") } ORDER BY ?verifiedAt",
  "params": [
    {
      "name": "changedAt",
      "type": "text",
      "required": true,
      "description": "changedAt parameter for this stored query."
    }
  ]
}

queries/camayoc_github_default_branch_ci:
{
  "action": "load",
  "name": "camayoc_github_default_branch_ci",
  "description": "github-activity Q4: for repository <repo>, the conclusion, head commit and time of the latest completed run of each workflow on branch <branch>. Answers gh-ci-watch's question from facts instead of a gh run list poll.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> SELECT DISTINCT ?workflow ?conclusion ?head ?at WHERE { GRAPH ?g0 { ?repo aegis:githubFullName \"{repo}\" . } GRAPH ?g { ?a aegis:githubEventKind \"workflow_run.completed\" ; aegis:inGitHubRepository ?repo ; aegis:aboutGitHubEntity ?run ; aegis:githubBaseRef \"{branch}\" ; aegis:githubConclusion ?conclusion ; aegis:commitSha ?head ; aegis:occurredAt ?at . } GRAPH ?g2 { ?run aegis:githubName ?workflow . } FILTER NOT EXISTS { GRAPH ?g3 { ?b aegis:githubEventKind \"workflow_run.completed\" ; aegis:inGitHubRepository ?repo ; aegis:aboutGitHubEntity ?run2 ; aegis:githubBaseRef \"{branch}\" ; aegis:occurredAt ?at2 . } GRAPH ?g4 { ?run2 aegis:githubName ?workflow . } FILTER(?at2 > ?at) } } ORDER BY ?workflow",
  "params": [
    {
      "name": "repo",
      "type": "text",
      "required": true,
      "description": "owner/name"
    },
    {
      "name": "branch",
      "type": "text",
      "required": true,
      "description": "branch name, e.g. main"
    }
  ]
}

queries/camayoc_github_participating_thr:
{
  "action": "load",
  "name": "camayoc_github_participating_threads",
  "description": "github-activity Q6: pull requests and issues where login <login> (lower-case) acted or was @-mentioned, with the latest activity time on each. Participation is judged here, at read time; it is never stored.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> SELECT ?thread ?kind (MAX(?at) AS ?last) WHERE { GRAPH ?g { ?a aegis:aboutGitHubEntity ?e ; aegis:occurredAt ?at . { ?a aegis:githubActorLogin ?who . FILTER(LCASE(STR(?who)) = \"{login}\") } UNION { ?a aegis:githubMentions \"{login}\" } } GRAPH ?g2 { { ?e aegis:onGitHubThread ?thread . } UNION { ?e a aegis:GitHubPullRequest . BIND(?e AS ?thread) } UNION { ?e a aegis:GitHubIssue . BIND(?e AS ?thread) } } GRAPH ?g3 { ?thread a ?kind . } } GROUP BY ?thread ?kind ORDER BY DESC(?last)",
  "params": [
    {
      "name": "login",
      "type": "text",
      "required": true,
      "description": "GitHub login, lower-case"
    }
  ]
}

{
  "action": "load",
  "name": "camayoc_github_pr_current_state",
  "description": "github-activity Q1: the state pull request <repo>#<number> was left in by its LATEST pull_request.* activity (state, merged, head, draft, kind, time). Current state is a read-time judgment over append-only GitHubActivity records in the github graph; nothing stores it.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> SELECT ?pr ?kind ?at ?state ?merged ?head ?draft ?baseSha ?mergeable ?mergeableState WHERE { GRAPH ?g0 { ?repo aegis:githubFullName \"{repo}\" . } GRAPH ?g1 { ?pr a aegis:GitHubPullRequest ; aegis:inGitHubRepository ?repo ; aegis:githubNumber ?n . } FILTER(STR(?n) = \"{number}\") GRAPH ?g { ?a aegis:aboutGitHubEntity ?pr ; aegis:githubEventKind ?kind ; aegis:occurredAt ?at ; aegis:githubState ?state . OPTIONAL { ?a aegis:githubMerged ?merged } OPTIONAL { ?a aegis:commitSha ?head } OPTIONAL { ?a aegis:githubDraft ?draft } OPTIONAL { ?a aegis:githubBaseSha ?baseSha } OPTIONAL { ?a aegis:githubMergeable ?mergeable } OPTIONAL { ?a aegis:githubMergeableState ?mergeableState } } FILTER(STRSTARTS(?kind, \"pull_request.\")) } ORDER BY DESC(?at) LIMIT 1",
  "params": [
    {
      "name": "repo",
      "type": "text",
      "required": true,
      "description": "owner/name"
    },
    {
      "name": "number",
      "type": "text",
      "required": true,
      "description": "pull request number"
    }
  ]
}

queries/camayoc_gp_backtest_outcomes.jso:
{
  "action": "load",
  "name": "camayoc_gp_backtest_outcomes",
  "description": "golden-paths Q13: did work items that conformed to this path close done more than the ones that deviated? Returns each follower's outcome and deviation so the rates are computed by the reader - the store holds facts, not the decaying judgment.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?trajectory ?workitem ?outcome ?deviation WHERE { ?trajectory a aegis:Trajectory ; aegis:followsPath <{path}> ; aegis:trajectoryOf ?workitem . OPTIONAL { ?workitem aegis:outcome ?outcome } OPTIONAL { ?trajectory aegis:deviatesAt ?deviation } } ORDER BY ?workitem",
  "params": [
    {
      "name": "path",
      "type": "iri",
      "required": true,
      "description": "path parameter for this stored query."
    }
  ]
}

