FILTER NOT EXISTS { ?item a:observes ?bad . ?bad a:observedAt ?badAt . FILTER(!REGEX(STR(?badAt), \"^(([0-9][0-9](0[48]|[2468][048]|[13579][26])|(0[48]|[2468][048]|[13579][26])00)-02-29|([0-9][0-9][0-9][1-9]|[0-9][0-9][1-9][0-9]|[0-9][1-9][0-9][0-9]|[1-9][0-9][0-9][0-9])-((0[13578]|1[02])-(0[1-9]|[12][0-9]|3[01])|(0[469]|11)-(0[1-9]|[12][0-9]|30)|02-(0[1-9]|1[0-9]|2[0-8])))T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\\\\.[0-9][0-9]?[0-9]?[0-9]?[0-9]?[0-9]?[0-9]?[0-9]?[0-9]?)?Z$\")) } FILTER NOT EXISTS { ?item a:observes ?peer . ?peer a:observedAt ?peerAt ; a:observedValue ?peerValue . BIND(CONCAT(\"t\", SUBSTR(STR(?peerAt),1,19), \".\", SUBSTR(CONCAT(IF(CONTAINS(STR(?peerAt),\".\"), STRBEFORE(STRAFTER(STR(?peerAt),\".\"),\"Z\"), \"\"), \"000000000\"),1,9)) AS ?peerKey) FILTER(?peerKey = ?latestKey) BIND(REPLACE(STR(?peerValue), \",\\\"kind\\\":\\\"(Plan|Design|Directive|DreamCycle)\\\"\", \"\") AS ?peerSnapshot) FILTER(?peerSnapshot != ?snapshot) } FILTER(?status = \"open\" || ?status = \"in_progress\") OPTIONAL { ?item a:about ?about } BIND(IF(REGEX(STR(?snapshot), \"\\\"assignee\\\":\\\"([^\\\"\\\\\\\\]*)\\\"\"), REPLACE(STR(?snapshot), \"^.*\\\"assignee\\\":\\\"([^\\\"\\\\\\\\]*)\\\".*$\", \"$1\"), \"\") AS ?owner) BIND(IF(CONTAINS(STR(?snapshot), '\"assignee\":null') || CONTAINS(STR(?snapshot), '\"assignee\":\"\"'), \"unassigned\", IF(REGEX(STR(?snapshot), \"\\\"assignee\\\":\\\"([^\\\"\\\\\\\\]*)\\\"\"), \"assigned\", \"unknown\")) AS ?ownerState) BIND(CONCAT(SUBSTR(?latestKey,2),\"Z\") AS ?observedAt) FILTER(CONTAINS(LCASE(STR(?snapshot)), LCASE(\"{topic}\"))) } ORDER BY DESC(?latestKey) ?item ?about LIMIT 100",
