queries/camayoc_wf_agent_activity_across:
{
  "action": "load",
  "name": "camayoc_wf_agent_activity_across_windows",
  "description": "workflow-and-archive Q8: everything one agent did across all runs in a time range, composing a hot window with a frozen one. The archive half is the question: a freeze archives a window without unbinding its IRI, so the frozen graph is still addressable and still composes back in. Against a live quipu the same query is issued with include_kinds [operational, archive] or FROM <urn:quipu:dataset:frozen> instead of naming each window; the FROMs here name them so the composition is explicit and testable. Omit the archive and the answer is quietly short \u2014 which is exactly the failure the question exists to catch.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?event ?run ?observedAt ?step ?fromState ?toState FROM <{window}> FROM <{archive}> WHERE { ?event a aegis:TransitionEvent ; aegis:performedBy <{principal}> ; aegis:inRun ?run ; aegis:fromState ?fromState ; aegis:toState ?toState ; aegis:observedAt ?observedAt . OPTIONAL { ?event aegis:atStep ?step } FILTER(?observedAt >= \"{from}\" && ?observedAt <= \"{to}\") } ORDER BY ?observedAt",
  "params": [
    {
      "name": "window",
      "type": "iri",
      "required": true,
      "description": "window parameter for this stored query."
    },
    {
      "name": "archive",
      "type": "iri",
      "required": true,
      "description": "archive parameter for this stored query."
    },
    {
      "name": "principal",
      "type": "iri",
      "required": true,
      "description": "principal parameter for this stored query."
    },
    {
      "name": "from",
      "type": "text",
      "required": true,
      "description": "from parameter for this stored query."
    },
    {
      "name": "to",
      "type": "text",
      "required": true,
      "description": "to parameter for this stored query."
    }
  ]
}

queries/camayoc_wf_declared_vs_traversed:
{
  "action": "load",
  "name": "camayoc_wf_declared_vs_traversed",
  "description": "workflow-and-archive Q5: the steps a workflow definition declares, against the ones a given run actually passed through. Composes the knowledge plane holding the definition with the operational window holding the run \u2014 the definition outlives the window and must not be frozen with it. A declared step the run never reached comes back with an EMPTY traversal time, which is the finding: a skipped step is absent from the transition log and must stay visibly absent rather than being filled in from the declaration.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?step ?stepLabel ?order ?traversedAt ?toState FROM <{definitions}> FROM <{window}> WHERE { <{definition}> aegis:hasStep ?step . ?step rdfs:label ?stepLabel ; aegis:stepOrder ?order . OPTIONAL { ?event a aegis:TransitionEvent ; aegis:inRun <{run}> ; aegis:atStep ?step ; aegis:observedAt ?traversedAt ; aegis:toState ?toState } } ORDER BY ?order",
  "params": [
    {
      "name": "definitions",
      "type": "iri",
      "required": true,
      "description": "definitions parameter for this stored query."
    },
    {
      "name": "window",
      "type": "iri",
      "required": true,
      "description": "window parameter for this stored query."
    },
    {
      "name": "definition",
      "type": "iri",
      "required": true,
      "description": "definition parameter for this stored query."
    },
    {
      "name": "run",
      "type": "iri",
