queries/camayoc_wf_plane_promotion_recor:
{
  "action": "load",
  "name": "camayoc_wf_plane_promotion_record",
  "description": "workflow-and-archive Q13, the move-rule half: when a fact was promoted out of crew:inferred, what the promotion recorded \u2014 which plane it left, which it entered, and whether the source interval was actually closed. camayoc:sourceLeftOpen is the load-bearing cell: false means scripts/promote_plane.py closed the source episode (a bitemporal interval close, never a delete), true means it could not name the source episode and said so rather than implying a close that never happened. GRAPH ?plane rather than a FROM parameter because the record lands in the TARGET plane and a caller asking whether a promotion happened does not yet know which that was. The second half of Q13 \u2014 is the original still visible as-of its write time \u2014 is quipu's bitemporal replay and not expressible here; the close being bitemporal is what makes the answer yes.",
  "template": "PREFIX camayoc: <https://camayoc.local/ontology/> SELECT ?plane ?record ?promotedFrom ?promotedInto ?sourceLeftOpen WHERE { GRAPH ?plane { <{fact}> camayoc:planePromotion ?record . ?record camayoc:promotedFrom ?promotedFrom ; camayoc:promotedInto ?promotedInto ; camayoc:sourceLeftOpen ?sourceLeftOpen } }",
  "params": [
    {
      "name": "fact",
      "type": "iri",
      "required": true,
      "description": "fact parameter for this stored query."
    }
  ]
}

queries/camayoc_wf_run_state_as_of.json:
{
  "action": "load",
  "name": "camayoc_wf_run_state_as_of",
  "description": "workflow-and-archive Q2: what state a run was in at an instant, read from the append-only transition log \u2014 the latest transition at or before the instant, and its toState. Answered from TransitionEvents rather than by valid-time slicing the re-asserted aegis:currentState facts: the two return the same state, the transition log is the truth currentState is derived from, and this form is answerable without a bitemporal store. BEFORE THE FIRST TRANSITION THERE IS NO ROW. That absence is the answer \u2014 the run's state before it was ever transitioned is not recorded, and returning a starting state nobody wrote would be inventing one.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?state ?event ?observedAt FROM <{window}> WHERE { ?event a aegis:TransitionEvent ; aegis:inRun <{run}> ; aegis:toState ?state ; aegis:observedAt ?observedAt . FILTER(?observedAt <= \"{instant}\") FILTER NOT EXISTS { ?later a aegis:TransitionEvent ; aegis:inRun <{run}> ; aegis:observedAt ?laterAt . FILTER(?laterAt <= \"{instant}\" && ?laterAt > ?observedAt) } }",
  "params": [
    {
      "name": "window",
      "type": "iri",
      "required": true,
      "description": "window parameter for this stored query."
    },
    {
      "name": "run",
      "type": "iri",
      "required": true,
      "description": "run parameter for this stored query."
    },
    {
      "name": "instant",
      "type": "text",
      "required": true,
      "description": "instant parameter for this stored query."
    }
  ]
}

queries/camayoc_wf_runs_in_window.json:
{
  "action": "load",
  "name": "camayoc_wf_runs_in_window",
  "description": "workflow-and-archive Q1: the runs of one workflow definition in one time window, with each run's current state. Window-scoped by an explicit FROM because that is what a window IS \u2014 the graph is quipu's unit of pack, attach, label and authority, and a query that forgot the FROM would answer across every month at once. currentState is the derived projection, not the truth; the transitions are the truth (Q2, Q3).",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?run ?label ?state ?startedAt FROM <{window}> WHERE { ?run a aegis:WorkflowRun ; aegis:runOf <{definition}> ; rdfs:label ?label ; aegis:currentState ?state . OPTIONAL { ?run aegis:createdAt ?startedAt } } ORDER BY ?startedAt",
  "params": [
