queries/camayoc_wf_transition_history.js:
{
  "action": "load",
  "name": "camayoc_wf_transition_history",
  "description": "workflow-and-archive Q3: the full transition history of one run \u2014 each step, from-state to to-state, in time order, with the agent that performed it. Append-only by design, so this is the complete record and not a reconstruction: fromState is carried ON the event rather than inferred from the previous row, which is what keeps a gap in the log visible as a gap. Composes the knowledge plane holding the definitions because a step's NAME lives with the definition, not in the window \u2014 the window records that a step was reached, the definition records what it is called. Compose only the window and the history is still complete; the step labels come back empty, which is absence shown rather than a name invented.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?event ?observedAt ?step ?stepLabel ?fromState ?toState ?agent FROM <{window}> FROM <{definitions}> WHERE { ?event a aegis:TransitionEvent ; aegis:inRun <{run}> ; aegis:fromState ?fromState ; aegis:toState ?toState ; aegis:observedAt ?observedAt . OPTIONAL { ?event aegis:atStep ?step . OPTIONAL { ?step rdfs:label ?stepLabel } } OPTIONAL { ?event aegis:performedBy ?agent } } ORDER BY ?observedAt",
  "params": [
    {
      "name": "window",
      "type": "iri",
      "required": true,
      "description": "window parameter for this stored query."
    },
    {
      "name": "definitions",
      "type": "iri",
      "required": true,
      "description": "definitions parameter for this stored query."
    },
    {
      "name": "run",
      "type": "iri",
      "required": true,
      "description": "run parameter for this stored query."
    }
  ]
}

queries/camayoc_wf_unverifiable_transiti:
{
  "action": "load",
  "name": "camayoc_wf_unverifiable_transitions",
  "description": "workflow-and-archive Q7: transitions in a window whose signature cannot be checked \u2014 either unsigned, or signed by an agent with no aegis:VerifierRegistration in the identity graph. The two are reported as DIFFERENT defects because they are: an unsigned transition never claimed provenance, a signature with no registered key claims it and cannot back it. Composes the window with the identity graph, which is dataKind identity and never frozen, so archived transitions stay checkable. This is detectable from day one, before any write-gate enforces it (quipu-8cc) \u2014 which is the whole point of the question. It does NOT verify the signature itself; no SPARQL query can (Q6).",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?event ?run ?agent ?observedAt ?signature ?defect FROM <{window}> FROM <{identity}> WHERE { ?event a aegis:TransitionEvent ; aegis:inRun ?run ; aegis:performedBy ?agent ; aegis:observedAt ?observedAt . OPTIONAL { ?event aegis:signature ?signature } OPTIONAL { ?registration a aegis:VerifierRegistration ; aegis:verifier ?agent } FILTER(!BOUND(?signature) || !BOUND(?registration)) BIND(IF(BOUND(?signature), \"signed by an agent with no verifier registration\", \"no signature at all\") AS ?defect) } ORDER BY ?observedAt",
  "params": [
    {
      "name": "window",
      "type": "iri",
      "required": true,
      "description": "window parameter for this stored query."
    },
    {
      "name": "identity",
      "type": "iri",
      "required": true,
      "description": "identity parameter for this stored query."
    }
  ]
}

queries/camayoc_wf_window_closeout.json:
{
  "action": "load",
  "name": "camayoc_wf_window_closeout",
  "description": "workflow-and-archive Q4: every run in a window with its outcome if it completed and its state if it is still open. COMPLETION IS READ FROM THE PRESENCE OF aegis:outcome, not from a list of terminal state names \u2014 aegis:outcome's own rule is that absence means open, and no term declares which state strings are terminal. A stored query carrying its own hardcoded terminal-state list would silently misclassify every workflow whose vocabulary differs from the one it was written against. This is also half of Q12, whose other half (is the window operational and unfrozen) is a meta-graph label no SPARQL query can reach.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?run ?label ?state ?status ?outcome ?closedAt FROM <{window}> WHERE { ?run a aegis:WorkflowRun ; rdfs:label ?label ; aegis:currentState ?state . OPTIONAL { ?run aegis:outcome ?outcome } OPTIONAL { ?run aegis:closedAt ?closedAt } BIND(IF(BOUND(?outcome), \"completed\", \"open\") AS ?status) } ORDER BY ?label",
  "params": [
    {
      "name": "window",
      "type": "iri",
      "required": true,
      "description": "window parameter for this stored query."
    }
  ]
}

queries/camayoc_work_item_burndown.json:
{
  "action": "load",
  "name": "camayoc_work_item_burndown",
  "description": "Event-derived active WorkItem balances and native created/closed transitions for ONE enrolled assignee/priority cohort. Reads only its explicit operational stream graph, never the tracker board. Opening balances are pinned enrollment, not invented history. Daily delta prefix sums produce balances. Latest checkpoint must be ready and fresh; missing or catching-up coverage is UNKNOWN. Same stored-query JSON layout as DORA.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX schema: <https://schema.org/> PREFIX seeds: <https://seeds.local/ontology/> SELECT ?metric ?status ?day ?value WHERE { { SELECT ?metric ?status ?day (SUM(?v) AS ?value) WHERE { GRAPH <{graph}> { ?o a aegis:Observation ; schema:additionalType ?kind ; aegis:observedAt ?at ; seeds:status ?status ; schema:value ?v . } BIND(STRAFTER(STR(?kind), \"urn:camayoc:work-item-burndown:\") AS ?metric) FILTER(?metric IN (\"opening\", \"delta\", \"created\", \"closed\") && STR(?at) < \"{end}\" && (?metric IN (\"opening\", \"delta\") || STR(?at) >= \"{start}\")) BIND(IF(?metric = \"opening\", STR(?at), IF(STR(?at) < \"{start}\", \"opening\", SUBSTR(STR(?at), 1, 10))) AS ?day) } GROUP BY ?metric ?status ?day } UNION { SELECT ?metric ?status (?at AS ?day) (?v AS ?value) WHERE { GRAPH <{graph}> { ?o a aegis:Observation ; schema:additionalType ?kind ; aegis:observedAt ?at ; seeds:status ?status ; schema:value ?v . } FILTER(?kind = <urn:camayoc:work-item-burndown:checkpoint>) BIND(\"checkpoint\" AS ?metric) } ORDER BY DESC(?at) LIMIT 1 } } ORDER BY ?metric ?status ?day",
  "params": [
    {
      "name": "graph",
      "type": "iri",
      "required": true,
      "description": "Exact enrolled WorkItem burn-down stream graph"
    },
    {
      "name": "start",
      "type": "text",
      "required": true,
      "description": "RFC3339 UTC start inclusive"
    },
    {
      "name": "end",
      "type": "text",
      "required": true,
      "description": "RFC3339 UTC end exclusive"
    }
  ]
}

queries/camayoc_work_item_token_cost.jso:
{
