queries/camayoc_work_per_token.json:
{
  "action": "load",
  "name": "camayoc_work_per_token",
  "description": "verification-and-liveness Q18: the two legs of work-per-token for a principal — items closed, and total tokens consumed. The ratio is left to the reader: dividing here would hide a zero denominator. Caveat, stated because it is SPARQL's doing: SUM over no records is 0, and 0-consumption and unmeasured are different claims — run Q19 (camayoc_sessions_without_usage) before believing a zero here.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX quechua: <https://scbrown.github.io/quechua/ns#> PREFIX schema: <https://schema.org/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?itemsClosed ?tokensConsumed WHERE { { SELECT (COUNT(DISTINCT ?item) AS ?itemsClosed) WHERE { { ?item a aegis:WorkItem ; aegis:assignedTo <{principal}> ; aegis:closedAt ?closedAt . } UNION { ?item a quechua:WorkItem ; aegis:assignedTo <{principal}> ; aegis:closedAt ?closedAt . } UNION { ?item a schema:Action ; schema:agent <{principal}> ; schema:endTime ?closedAt . } } } { SELECT (SUM(?tokens) AS ?tokensConsumed) WHERE { ?record a aegis:UsageRecord ; aegis:inSession ?session ; aegis:tokensConsumed ?tokens . ?session aegis:actor <{principal}> . } } }",
  "params": [
    {
      "name": "principal",
      "type": "iri",
      "required": true,
      "description": "Principal IRI."
    }
  ]
}

queries/mem_decision_history.json:
{
  "action": "load",
  "description": "Every version of one decision key, newest first, superseded ones included. Generated from tools/memory/decision.tool.json; drops superseded and expired records, ranks declared > observed > inferred, at most 50 rows plus one overflow sentinel.",
  "name": "mem_decision_history",
  "params": [
    {
      "description": "The crew:declared plane graph IRI (filled by cy from its plane table).",
      "name": "declared",
      "required": true,
      "type": "iri"
    },
    {
      "description": "The crew:records plane graph IRI (filled by cy from its plane table).",
      "name": "records",
      "required": true,
      "type": "iri"
    },
    {
      "description": "The crew:inferred plane graph IRI (filled by cy from its plane table).",
      "name": "inferred",
      "required": true,
      "type": "iri"
    },
    {
      "description": "The natural-key IRI whose versions to list.",
      "name": "key",
      "required": true,
      "type": "iri"
    }
  ],
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?iri ?naturalKey (\"decision\" AS ?kind) ?label (GROUP_CONCAT(DISTINCT STR(?b); separator=\" | \") AS ?body) ?sourceKind ?recordedAt ?supersedes FROM <{declared}> FROM <{records}> FROM <{inferred}> WHERE { ?iri a aegis:Decision ; aegis:naturalKey ?naturalKey ; rdfs:label ?label ; aegis:sourceKind ?sourceKind ; aegis:recordedAt ?recordedAt ; aegis:chose ?b . FILTER(?naturalKey = <{key}>) OPTIONAL { ?iri aegis:supersedes ?supersedes } BIND(IF(?sourceKind = \"declared\", 0, IF(?sourceKind = \"observed\", 1, 2)) AS ?rank) } GROUP BY ?iri ?naturalKey ?label ?sourceKind ?recordedAt ?supersedes ?rank ORDER BY DESC(?recordedAt) ?iri LIMIT 51"
}

