  "name": "repo_review_mode",
  "description": "aegis-za4f.17.1: review mode of one repository (aegis:reviewMode on aegis:GitRepo: non-author or none). Param repo = 'owner/name', matched EXACTLY against rdfs:label or skos:altLabel; the owner is never discarded, so a fact on another owner's node cannot answer (fail closed). Returns every matching row: the caller treats no rows or conflicting rows as non-author. 64 rows is an overflow sentinel.",
  "template": "PREFIX aegis: <http://aegis.gastown.local/ontology/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX skos: <http://www.w3.org/2004/02/skos/core#>\nSELECT DISTINCT ?node ?mode WHERE {\n  VALUES ?key { '{repo}' }\n  ?node a aegis:GitRepo ; aegis:reviewMode ?mode .\n  { ?node rdfs:label ?term } UNION { ?node skos:altLabel ?term }\n  FILTER(STR(?term) = ?key)\n}\nORDER BY ?node ?mode\nLIMIT 64",
  "params": [
    {
      "name": "repo",
      "type": "text",
      "required": true,
      "description": "Repository as 'owner/name' (e.g. 'intigraph/quipu')."
    }
  ]
}

shapes/agent-memory.shapes.ttl:
# camayoc agent-memory shapes (docs/design/agent-memory-entities.md §2, §3)
#
# The source of truth for every agent-memory create tool. Each property says:
#   sh:name         the argument name (CLI flag = kebab-case of it, MCP arg = it)
#   sh:description  the help text every surface prints
#   sh:message      the plain-word refusal, naming the flag
# `scripts/memory_tools.py` reads this file plus tools/memory/*.tool.json and
# generates every surface; its lint fails the build on a minCount without an
# sh:message (the 10/27 "unnamed field" bug class).
#
# Shared fields (label, naturalKey, sourceKind, recordedAt, recordedBy,
# contentHash, lifecycle) are filled by the tool, never by the caller, and are
# checked by MemoryRecordShape so a tool bug is refused like any other write.
#
# NOT loaded into production quipu by this change: the Decision and Directive
# shapes tighten classes that already have live nodes, and the Decision shape
# needs the quipu GateApproval split first (design §1.3). See the schema
# proposal note in docs/design/agent-memory-entities.md §7.

@prefix aegis: <http://aegis.gastown.local/ontology/> .
@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .
@prefix prov:  <http://www.w3.org/ns/prov#> .

# ---- Shared record fields (tool-filled) -------------------------------------

aegis:MemoryRecordShape a sh:NodeShape ;
    sh:targetSubjectsOf aegis:naturalKey ;
    sh:property [
        sh:path aegis:naturalKey ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:name "naturalKey" ;
        sh:description "The record's natural-key IRI (aegis:mem/<kind>/<scope>/<topic>); filled by the tool." ;
        sh:message "Not recorded: the record has no natural key (camayoc tool bug; report it)." ] ;
    sh:property [
        sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:name "label" ;
        sh:description "One-line label; filled by the tool from the record body." ;
        sh:message "Not recorded: the record has no label (camayoc tool bug; report it)." ] ;
    sh:property [
        sh:path aegis:sourceKind ; sh:minCount 1 ; sh:maxCount 1 ;
        sh:in ( "observed" "declared" "inferred" ) ;
        sh:name "sourceKind" ;
        sh:description "Provenance tag: observed, declared or inferred; filled by the tool's sourceKind rule." ;
        sh:message "Not recorded: the record needs exactly one sourceKind of observed, declared or inferred." ] ;
    sh:property [
        sh:path aegis:recordedAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ;
        sh:name "recordedAt" ;
        sh:description "UTC instant the record was written; filled by the tool." ;
        sh:message "Not recorded: the record has no recordedAt instant (camayoc tool bug; report it)." ] ;
    sh:property [
        sh:path aegis:recordedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:name "recordedBy" ;
        sh:description "The agent that wrote the record ($SHANTY_AGENT or the harness agent id); filled by the tool." ;
        sh:message "Not recorded: the record does not say which agent wrote it; set SHANTY_AGENT." ] ;
    sh:property [
        sh:path aegis:contentHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:pattern "^sha256:[0-9a-f]{64}$" ;
        sh:name "contentHash" ;
        sh:description "sha256 over the caller-supplied fields; how an unchanged re-record is detected." ;
        sh:message "Not recorded: the record has no content hash (camayoc tool bug; report it)." ] ;
    sh:property [
        sh:path aegis:supersedes ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:name "supersedes" ;
        sh:description "The earlier version this record replaces; filled by the tool on the same natural key." ;
        sh:message "Not recorded: a record supersedes at most one earlier version, by IRI." ] ;
    sh:property [
        sh:path aegis:supersededAt ; sh:maxCount 1 ; sh:datatype xsd:dateTime ;
        sh:name "supersededAt" ;
        sh:description "UTC instant the supersededBy link was written; the cursor bobbin's feed uses to drop the record." ;
        sh:message "Not recorded: a record is superseded once, at one UTC instant." ] .

aegis:MemoryTopicShape a sh:NodeShape ;
    sh:targetClass aegis:MemoryTopic ;
    sh:property [
        sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:name "label" ;
        sh:description "The topic's registered name, kebab-case." ;
        sh:message "Not recorded: a topic needs one name (cy topic add <name>)." ] ;
    sh:property [
        sh:path aegis:alias ; sh:datatype xsd:string ;
        sh:name "alias" ;
        sh:description "Another spelling that resolves to this topic." ;
        sh:message "Not recorded: a topic alias is plain text." ] .

# ---- Decision: one ruling on a scoped question ------------------------------
# aegis:Decision is the memory Decision (design §1.3 ruling). `by` is stored on
# aegis:decidedBy, an IRI, so it never collides with the governance aegis:by
# literal that quipu's GateApproval shape requires.

aegis:MemoryDecisionShape a sh:NodeShape ;
    sh:targetClass aegis:Decision ;
    sh:property [
        sh:path aegis:chose ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 1 ; sh:name "chose" ;
        sh:description "What was chosen, in one sentence." ;
        sh:message "Not recorded: a decision needs what was chosen (--chose)." ] ;
    sh:property [
        sh:path aegis:decidedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 2 ; sh:name "by" ;
        sh:description "Who ruled: a Person or agent entity (IRI or local name)." ;
        sh:message "Not recorded: a decision needs who ruled (--by), as an existing person or agent." ] ;
    sh:property [
        sh:path aegis:about ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 3 ; sh:name "about" ;
        sh:description "The entity the decision is about: host, repo, service, role, agent or person (IRI or local name)." ;
        sh:message "Not recorded: a decision needs what it is about (--about), as an existing entity." ] ;
    sh:property [
        sh:path aegis:topic ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 4 ; sh:name "topic" ;
        sh:description "The registered memory topic the decision answers (cy topic add registers one)." ;
        sh:message "Not recorded: a decision needs a registered topic (--topic)." ] ;
    sh:property [
        sh:path aegis:over ; sh:datatype xsd:string ;
        sh:order 5 ; sh:name "over" ;
        sh:description "An alternative that was not chosen; repeat for each." ;
        sh:message "Not recorded: --over is plain text, one alternative per flag." ] ;
    sh:property [
        sh:path aegis:rationale ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 6 ; sh:name "rationale" ;
        sh:description "Why, in one or two sentences." ;
        sh:message "Not recorded: give one --rationale." ] ;
    sh:property [
        sh:path aegis:decidedIn ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 7 ; sh:name "decidedIn" ;
        sh:description "The board item or session the decision was made in (IRI or local name)." ;
        sh:message "Not recorded: --decided-in names one board item or session." ] ;
    sh:property [
        sh:path aegis:verbatim ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 8 ; sh:name "verbatim" ;
        sh:description "The ruling in the decider's own words." ;
        sh:message "Not recorded: give one --verbatim quote." ] .

# ---- Directive: a standing rule ---------------------------------------------

aegis:MemoryDirectiveShape a sh:NodeShape ;
    sh:targetClass aegis:Directive ;
    sh:property [
        sh:path aegis:rule ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 1 ; sh:name "rule" ;
        sh:description "The rule, as one imperative sentence." ;
        sh:message "Not recorded: a directive needs the rule as one imperative sentence (--rule)." ] ;
    sh:property [
        sh:path aegis:issuedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 2 ; sh:name "issuedBy" ;
        sh:description "Who issued the rule: a Person or agent entity (IRI or local name)." ;
        sh:message "Not recorded: a directive needs who issued it (--issued-by), as an existing person or agent." ] ;
    sh:property [
        sh:path aegis:appliesTo ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 3 ; sh:name "appliesTo" ;
        sh:description "Who or what the rule binds: an agent, CrewRole or repo, or 'crew' for everyone." ;
        sh:message "Not recorded: a directive needs who it applies to (--applies-to), an existing agent, role or repo, or 'crew'." ] ;
    sh:property [
        sh:path aegis:topic ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 4 ; sh:name "topic" ;
        sh:description "The registered memory topic the rule governs (cy topic add registers one)." ;
        sh:message "Not recorded: a directive needs a registered topic (--topic)." ] ;
    sh:property [
        sh:path aegis:issuedOn ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ;
        sh:order 5 ; sh:name "issuedOn" ;
        sh:description "The date the rule was given, YYYY-MM-DD." ;
        sh:message "Not recorded: --issued-on is one date, YYYY-MM-DD." ] ;
    sh:property [
        sh:path aegis:why ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 6 ; sh:name "why" ;
        sh:description "Why the rule exists, in one sentence." ;
        sh:message "Not recorded: give one --why." ] ;
    sh:property [
        sh:path aegis:verbatim ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 7 ; sh:name "verbatim" ;
        sh:description "The rule in the issuer's own words." ;
        sh:message "Not recorded: give one --verbatim quote." ] ;
    sh:property [
        sh:path <https://w3id.org/intigraph/quechua/ns#traceabilityDueAt> ;
        sh:maxCount 1 ; sh:datatype xsd:dateTime ;
        sh:order 8 ; sh:name "traceabilityDueAt" ;
        sh:description "Explicit timezone-bearing evaluation deadline when policy/work-item traceability is deferred; no automatic date is chosen." ;
        sh:message "Not recorded: --traceability-due-at needs one valid timezone-bearing dateTime." ] .

# ---- Preference: how a person wants things done -----------------------------

aegis:MemoryPreferenceShape a sh:NodeShape ;
    sh:targetClass aegis:Preference ;
    sh:property [
        sh:path aegis:person ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 1 ; sh:name "person" ;
        sh:description "Whose preference it is: a Person entity (IRI or local name)." ;
        sh:message "Not recorded: a preference needs whose it is (--person), as an existing person." ] ;
    sh:property [
        sh:path aegis:prefers ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 2 ; sh:name "prefers" ;
        sh:description "What the person prefers, in one sentence." ;
        sh:message "Not recorded: a preference needs what is preferred, in one sentence (--prefers)." ] ;
    sh:property [
        sh:path aegis:context ; sh:minCount 1 ; sh:maxCount 1 ;
        sh:in ( "email" "chat" "code-review" "document" "artifact" "form" "travel" ) ;
        sh:order 3 ; sh:name "context" ;
        sh:description "Where it applies: email, chat, code-review, document, artifact, form or travel." ;
        sh:message "Not recorded: a preference needs a context (--context): email, chat, code-review, document, artifact, form or travel." ] ;
    sh:property [
        sh:path aegis:topic ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 4 ; sh:name "topic" ;
        sh:description "The registered memory topic (cy topic add registers one)." ;
        sh:message "Not recorded: a preference needs a registered topic (--topic)." ] ;
    sh:property [
        sh:path aegis:notWhen ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 5 ; sh:name "notWhen" ;
        sh:description "When the preference does not apply." ;
        sh:message "Not recorded: give one --not-when." ] ;
    sh:property [
        sh:path aegis:example ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 6 ; sh:name "example" ;
        sh:description "One short example of the preference applied." ;
        sh:message "Not recorded: give one --example." ] ;
    sh:property [
        sh:path aegis:verbatim ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 7 ; sh:name "verbatim" ;
        sh:description "The preference in the person's own words." ;
        sh:message "Not recorded: give one --verbatim quote." ] .

# ---- Handoff: one current note per agent ------------------------------------

aegis:MemoryHandoffShape a sh:NodeShape ;
    sh:targetClass aegis:Handoff ;
    sh:property [
        sh:path aegis:agent ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 1 ; sh:name "agent" ;
        sh:description "The agent the handoff is for (IRI or local name)." ;
        sh:message "Not recorded: a handoff needs the agent it is for (--agent), as an existing agent." ] ;
    sh:property [
        sh:path aegis:next ; sh:minCount 1 ; sh:maxCount 7 ; sh:datatype xsd:string ;
        sh:order 2 ; sh:name "next" ;
        sh:description "A next step pointing at a board item, PR or entity; repeat, 1 to 7." ;
        sh:message "Not recorded: a handoff needs 1 to 7 next steps (--next), each pointing at a board item, PR or entity." ] ;
    sh:property [
        sh:path aegis:waitingOn ; sh:maxCount 7 ; sh:datatype xsd:string ;
        sh:order 3 ; sh:name "waitingOn" ;
        sh:description "What an item waits on; repeat, at most 7." ;
        sh:message "Not recorded: at most 7 --waiting-on lines." ] ;
    sh:property [
        sh:path aegis:handoffContext ; sh:maxCount 3 ; sh:datatype xsd:string ;
        sh:order 4 ; sh:name "context" ;
        sh:description "Context the next session needs; repeat, at most 3 lines." ;
        sh:message "Not recorded: at most 3 --context lines; item state belongs on the board." ] .

# ---- Reference: where a system lives and how to reach it --------------------

aegis:MemoryReferenceShape a sh:NodeShape ;
    sh:targetClass aegis:Reference ;
    sh:property [
        sh:path aegis:subject ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 1 ; sh:name "subject" ;
        sh:description "The system the reference points into: host, service, repo or tool (IRI or local name)." ;
        sh:message "Not recorded: a reference needs the system it points into (--subject), as an existing entity." ] ;
    sh:property [
        sh:path aegis:topic ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 2 ; sh:name "topic" ;
        sh:description "What the reference is for: a registered memory topic (cy topic add registers one)." ;
        sh:message "Not recorded: a reference needs a registered topic saying what it is for (--topic)." ] ;
    sh:property [
        sh:path aegis:locator ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 3 ; sh:name "locator" ;
        sh:description "Where it is: a URL, path, command or graph IRI. Never a secret." ;
        sh:message "Not recorded: a reference needs where it is (--locator): a URL, path, command or graph IRI." ] ;
    sh:property [
        sh:path aegis:secretRef ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:pattern "^[A-Za-z][A-Za-z0-9_./-]{1,127}$" ;
        sh:order 4 ; sh:name "secretRef" ;
        sh:description "The secret-store key name that holds the credential. A key name, never a value." ;
        sh:message "Not recorded: --secret-ref must be a secret-store key name, not a value." ] ;
    sh:property [
        sh:path aegis:access ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 5 ; sh:name "access" ;
        sh:description "How to authenticate, in one sentence, without the secret." ;
        sh:message "Not recorded: give one --access sentence." ] .

shapes/core.shapes.ttl:
# camayoc core shapes — the gate (slice 1: work + decisions)
#
# Posture (inherited, deliberate): PERMISSIVE on domain shape, STRICT on the
# provenance tag. sourceKind is the reader's only signal of trust, so it is
# closed-vocabulary and mandatory from the first load; domain properties
# start permissive and tighten deliberately.
#
# Same base-namespace note as ontology/core.ttl: targets are declared in the
# store's default base_ns so /episode writes and these shapes agree out of
# the box.

@prefix aegis: <http://aegis.gastown.local/ontology/> .
@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .
@prefix schema: <https://schema.org/> .
@prefix quipu: <http://quipu.dev/ontology/> .

# Work-item validation belongs to the pinned Seeds profile (schema:Action).
# See shapes/aegis/seeds-profile.json; legacy names are deprecated aliases only.

# Workflow linkage is a producer-owned property constraint, not another tracker
# shape. It applies to canonical Actions and to retained historical records.
aegis:ActionWorkflowRunShape a sh:NodeShape ;
    sh:targetSubjectsOf aegis:inWorkflowRun ;
    sh:property [ sh:path aegis:inWorkflowRun ; sh:maxCount 1 ; sh:class aegis:WorkflowRun ] .

# Retained legacy relation checks do not sanction new WorkItem writes. New work
# uses quechua:blockedOn on schema:Action, governed by the Seeds profile.
aegis:LegacyBlockedOnShape a sh:NodeShape ;
    sh:targetSubjectsOf aegis:blockedOn ;
    sh:property [ sh:path aegis:blockedOn ;
                  sh:or ( [ sh:class aegis:WorkItem ] [ sh:class schema:Action ] [ sh:class aegis:Blocker ] ) ] .

# A declared review age must be machine-readable, or the reactor can never
# tell due from not-due (aegis-kxjack). Any subject that declares one is
# checked; months and years are refused, because their length is ambiguous.
aegis:CamayocReviewAgeShape a sh:NodeShape ;
    sh:targetSubjectsOf aegis:reviewAfter , aegis:maxAge , aegis:idleLimit ;
    sh:property [
        sh:path aegis:reviewAfter ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}(T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]+)?)?(Z|[+-][0-9]{2}:[0-9]{2}))?$" ;
        sh:message "camayoc: reviewAfter is one ISO-8601 date or UTC-offset instant" ;
    ] ;
    sh:property [
        sh:path aegis:maxAge ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:pattern "^P([0-9]+W|[0-9]+D|([0-9]+D)?T([0-9]+H([0-9]+M)?|[0-9]+M))$" ;
        sh:message "camayoc: maxAge is one ISO-8601 duration in weeks, days, hours or minutes (no months or years)" ;
    ] ;
    # No maxCount: a WorkItem is re-emitted byte-identically, so a kind change APPENDS
    # a second limit and a maxCount would refuse that item's every later write. Each
    # value is its own basis instead; the earliest lapse wins (aegis-qx96wr).
    sh:property [
        sh:path aegis:idleLimit ;
        sh:datatype xsd:string ;
        sh:pattern "^P([0-9]+W|[0-9]+D|([0-9]+D)?T([0-9]+H([0-9]+M)?|[0-9]+M))$" ;
        sh:message "camayoc: idleLimit is an ISO-8601 duration in weeks, days, hours or minutes (no months or years)" ;
    ] ;
    sh:property [
        sh:path aegis:workKind ;
        sh:datatype xsd:string ;
        sh:in ("Directive" "Design" "Plan" "DreamCycle" "DreamLane") ;
        sh:message "camayoc: workKind is one of Directive|Design|Plan|DreamCycle|DreamLane" ;
    ] .

aegis:CamayocDecisionShape a sh:NodeShape ;
    sh:targetClass aegis:Decision ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every Decision carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Decision needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:chose ;
        sh:minCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Decision without 'chose' is not a decision — record what was chosen" ;
    ] .

# Verification is deliberately stricter than the founding WorkItem/Decision
# shapes: its whole claim to trust is that it names the result that could have
# proved it wrong.  This is an ingress obligation, not a convention for a
# reader to remember.
aegis:CamayocVerificationShape a sh:NodeShape ;
    sh:targetClass aegis:Verification ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every Verification carries exactly one sourceKind of observed|declared|inferred — the tag is the reader's only signal of trust" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Verification needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:falsifier ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Verification without a falsifier is an assertion, not verification — record the result that would have proved it wrong" ;
    ] ;
    sh:property [
        sh:path aegis:adversariallyProvenBy ;
        sh:class aegis:Verification ;
        sh:message "camayoc: an adversarial proof must itself be a Verification — sabotage that cannot name what flipping looks like proves nothing" ;
    ] .

# An execution path makes the running artifact and refresh chain queryable.
# It intentionally has no `isLive` field: live is a read-time verdict, while
# each property here is an observed or declared fact that remains true later.
aegis:CamayocExecutionPathShape a sh:NodeShape ;
    sh:targetClass aegis:ExecutionPath ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every ExecutionPath carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: an ExecutionPath needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:executesArtifact ;
        sh:minCount 1 ;
        sh:message "camayoc: an ExecutionPath must name the artifact that actually executes" ;
    ] ;
    sh:property [
        sh:path aegis:repositorySource ;
        sh:minCount 1 ;
        sh:message "camayoc: an ExecutionPath must name the repository source to compare with its executed artifact" ;
    ] ;
    sh:property [
        sh:path aegis:refreshedBy ;
        sh:minCount 1 ;
        sh:message "camayoc: an ExecutionPath must name what refreshes its artifact" ;
    ] .

# The type-level distinction is deliberately mandatory. A stated ticket claim
# can be useful, but it must never read as a built reproduction. The optional
# demonstration link is type-checked when present; the producer integration
# that emits it belongs with yupana/quipu, not a made-up write-time liveness rule.
aegis:CamayocBlockerShape a sh:NodeShape ;
    sh:targetClass aegis:Blocker ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every Blocker carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Blocker needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:blockerEvidence ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("stated" "built") ;
        sh:message "camayoc: a Blocker must say whether its evidence is stated or built" ;
    ] ;
    sh:property [
        sh:path aegis:demonstratedBy ;
        sh:class aegis:Verification ;
        sh:message "camayoc: blocker demonstration must be a Verification" ;
    ] ;
    sh:property [
        sh:path aegis:blockerKind ;
        sh:maxCount 1 ;
        sh:in ("release-installed" "pr-merged" "ci-green" "human-action" "date") ;
        sh:message "camayoc: blockerKind is one of release-installed|pr-merged|ci-green|human-action|date" ;
    ] ;
    sh:property [
        sh:path aegis:resolutionQuery ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Blocker carries at most one resolutionQuery (a SPARQL ASK)" ;
    ] ;
    sh:property [
        sh:path aegis:resolvesOn ;
        sh:maxCount 1 ;
        sh:datatype xsd:date ;
        sh:message "camayoc: resolvesOn is one xsd:date" ;
    ] ;
    # A KINDED blocker (a condition work waits on) must be checkable: the
    # parameters its kind's probe needs. An unkinded one is a stated reason, as
    # before (aegis-c0awwp). The probe CODE lives in camayoc, never in the graph.
    sh:or (
        [ sh:path aegis:blockerKind ; sh:maxCount 0 ]
        [ sh:and (
            [ sh:path aegis:blockerKind ; sh:hasValue "pr-merged" ]
            [ sh:path aegis:prRef ; sh:minCount 1 ; sh:maxCount 1 ;
              sh:pattern "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+\u0023[0-9]+$" ] ) ]
        [ sh:and (
            [ sh:path aegis:blockerKind ; sh:hasValue "release-installed" ]
            [ sh:path aegis:tool ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern "^[A-Za-z0-9_.-]+$" ]
            [ sh:path aegis:minVersion ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern "^[0-9]+(\\.[0-9]+)*$" ] ) ]
        [ sh:and (
            [ sh:path aegis:blockerKind ; sh:hasValue "ci-green" ]
            [ sh:path aegis:repoRef ; sh:minCount 1 ; sh:maxCount 1 ;
              sh:pattern "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+@[A-Za-z0-9_./-]+$" ] ) ]
        [ sh:and (
            [ sh:path aegis:blockerKind ; sh:hasValue "human-action" ]
            [ sh:path aegis:resolutionQuery ; sh:minCount 1 ] ) ]
        [ sh:and (
            [ sh:path aegis:blockerKind ; sh:hasValue "date" ]
            [ sh:path aegis:resolvesOn ; sh:minCount 1 ] ) ]
    ) ;
    sh:message "camayoc: a kinded Blocker must carry its kind's probe parameters (pr-merged: prRef owner/repo\u0023N; release-installed: tool + minVersion; ci-green: repoRef owner/repo@branch; human-action: resolutionQuery; date: resolvesOn)" .

aegis:CamayocTrackerObservationStatusShape a sh:NodeShape ;
    sh:targetClass aegis:Observation ;
    sh:property [
        sh:path aegis:observedStatus ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: an Observation records at most one observedStatus" ;
    ] ;
    sh:property [
        sh:path aegis:observedClosedAt ;
        sh:maxCount 1 ;
        sh:message "camayoc: an Observation records at most one observedClosedAt" ;
    ] ;
    sh:property [
        sh:path aegis:observedBlockedOn ;
        sh:nodeKind sh:IRI ;
        sh:message "camayoc: observedBlockedOn points at a work item IRI (it may be projected before its target is)" ;
    ] .

aegis:CamayocNonFunctionalRequirementShape a sh:NodeShape ;
    sh:targetClass aegis:NonFunctionalRequirement ;
    sh:property [ sh:path aegis:sourceKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:in ("declared") ] ;
    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:about ; sh:minCount 1 ] ;
    sh:property [ sh:path aegis:threshold ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:unit ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:measurementWindow ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:ownedBy ; sh:minCount 1 ; sh:maxCount 1 ] ;
    sh:property [ sh:path aegis:createdAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] .

aegis:CamayocMetricShape a sh:NodeShape ;
    sh:targetClass aegis:Metric ;
    sh:property [ sh:path aegis:sourceKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:in ("declared") ] ;
    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:unit ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:meaning ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:ownedBy ; sh:minCount 1 ; sh:maxCount 1 ] ;
    sh:property [ sh:path aegis:probe ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:measuresRequirement ; sh:minCount 1 ; sh:maxCount 1 ; sh:class aegis:NonFunctionalRequirement ] ;
    sh:property [ sh:path quipu:derivedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ] ;
    sh:property [ sh:path aegis:contentHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] .

# The four minCount requirements of an Observation are write-validation
# debt: see shapes/observation-debt.shapes.ttl (aegis-g51c C10).
aegis:CamayocObservationShape a sh:NodeShape ;
    sh:targetClass aegis:Observation ;
    sh:property [ sh:path aegis:sourceKind ; sh:maxCount 1 ; sh:in ("observed") ] ;
    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:observedAt ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path aegis:observedValue ; sh:maxCount 1 ; sh:datatype xsd:string ] .

aegis:CamayocMetricDerivationShape a sh:NodeShape ;
    sh:targetSubjectsOf quipu:derivationSystem ;
    sh:property [ sh:path quipu:derivationSystem ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path quipu:derivationQuery ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;
    sh:property [ sh:path quipu:derivationParams ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] .

# ---- Golden paths (slice: trajectories, blessing, conformance) ----------
# Same posture: strict on the provenance tag and on the properties whose
# absence makes the node a lie (a path without its exemplar, an omission
# without its authority, a promotion without its promoter); permissive on
# everything else, tightened deliberately.

aegis:CamayocTrajectoryShape a sh:NodeShape ;
    sh:targetClass aegis:Trajectory ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every Trajectory carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Trajectory needs exactly one rdfs:label" ;
    ] .

aegis:CamayocStepShape a sh:NodeShape ;
    sh:targetClass aegis:Step ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every Step carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Step needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:stepOf ;
        sh:minCount 1 ;
        sh:message "camayoc: a Step must name its Trajectory — a step with no trajectory is an anecdote" ;
    ] .

aegis:CamayocGoldenPathShape a sh:NodeShape ;
    sh:targetClass aegis:GoldenPath ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every GoldenPath carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a GoldenPath needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:prunedFrom ;
        sh:minCount 1 ;
        sh:message "camayoc: a GoldenPath must cite the exemplar Trajectory it was pruned from — a path that cannot cite the concrete success justifying it is an opinion" ;
    ] .

aegis:CamayocPathOmissionShape a sh:NodeShape ;
    sh:targetClass aegis:PathOmission ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every PathOmission carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a PathOmission needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:omittedStep ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "camayoc: a PathOmission names exactly one omitted Step" ;
    ] ;
    sh:property [
        sh:path aegis:omissionAuthority ;
        sh:minCount 1 ;
        sh:in ("cone-analysis" "human-decision") ;
        sh:message "camayoc: an omission must carry its authority — cone-analysis or human-decision. An omission that cannot say who cut it is a silent edit of history" ;
    ] .

aegis:CamayocPathPromotionShape a sh:NodeShape ;
    sh:targetClass aegis:PathPromotion ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed" "declared" "inferred") ;
        sh:message "camayoc: every PathPromotion carries exactly one sourceKind of observed|declared|inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a PathPromotion needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:promotes ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "camayoc: a PathPromotion names exactly one GoldenPath it promotes" ;
    ] ;
    sh:property [
        sh:path aegis:blessingLevel ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("candidate" "advisory" "blessed" "constraint-backing") ;
        sh:message "camayoc: a promotion's level is one of candidate|advisory|blessed|constraint-backing — recorded and verified are mechanical read-time states, not promotions" ;
    ] ;
    sh:property [
        sh:path aegis:promotedBy ;
        sh:minCount 1 ;
        sh:message "camayoc: a promotion without its promoting principal is not a human act — nothing above verified happens without one" ;
    ] ;
    sh:property [
        sh:path aegis:promotedAt ;
        sh:minCount 1 ;
        sh:message "camayoc: a promotion carries when it happened" ;
    ] .

# ---- Cost and effort accounting (verification-and-liveness §D) -----------
# Deterministic-parser facts, so the posture is the Observation shape's:
# sourceKind is pinned to "observed" — a declared or inferred usage number
# is not an account of consumption, it is an estimate wearing one's clothes.
# No gate-probe arm: like the metrics-slice shapes (Metric, Observation),
# these carry no suite-stated proof obligation; the probe arms stay the
# M1/M3/M4 + golden-paths set the suite itself demands.

aegis:CamayocSessionShape a sh:NodeShape ;
    sh:targetClass aegis:Session ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed") ;
        sh:message "camayoc: a Session is parsed from the harness's own record and enters as observed — Q19's denominator cannot be hand-declared" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a Session needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:actor ;
        sh:minCount 1 ;
        sh:message "camayoc: a Session names the principal that ran it — per-principal consumption (Q17, Q18) joins on this" ;
    ] .

aegis:CamayocUsageRecordShape a sh:NodeShape ;
    sh:targetClass aegis:UsageRecord ;
    sh:property [
        sh:path aegis:sourceKind ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:in ("observed") ;
        sh:message "camayoc: a UsageRecord is a deterministic-parser fact and enters as observed — never declared, never inferred" ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a UsageRecord needs exactly one rdfs:label" ;
    ] ;
    sh:property [
        sh:path aegis:inSession ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:class aegis:Session ;
        sh:message "camayoc: a UsageRecord is anchored to exactly one Session — an unattached record can join against nothing" ;
    ] ;
    sh:property [
        sh:path aegis:provider ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a UsageRecord names its provider — Q17 and Q20 group by it" ;
    ] ;
    sh:property [
        sh:path aegis:tokensConsumed ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:integer ;
        sh:message "camayoc: a UsageRecord carries exactly one consumption count — a record without its measurement is nothing, and a missing measurement must stay missing, never aggregate as zero" ;
    ] ;
    sh:property [
        sh:path aegis:observedAt ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "camayoc: a UsageRecord carries when the consumption happened — burn rate (Q20) is a read-time judgment over these timestamps" ;
    ] ;
    sh:property [
        sh:path aegis:attributedTo ;
        # Retained records may still name an old WorkItem. Replacement metadata
        # does not retype those records, and this compatibility reference grants
        # no permission to create new deprecated work-item records.
        sh:or ( [ sh:class schema:Action ] [ sh:class aegis:WorkItem ] ) ;
        sh:message "camayoc: usage attribution, when present, points at a Seeds Action or retained WorkItem — cost as a property of work, not of a window" ;
    ] .

# aegis:ownedBy names a PRINCIPAL, so its object is an IRI on every subject, not
# only on the classes shaped above. One literal ("aegis-crew") among 591 IRI
# owners was invisible to every reader that joins the owner to a principal or
# crew node: owner routing and the ownership views silently skipped it
# (aegis-j32oup). Targeted by subject, so a new class that uses ownedBy is
# covered without anyone remembering to add it here.
aegis:CamayocOwnedByIsIriShape a sh:NodeShape ;
    sh:targetSubjectsOf aegis:ownedBy ;
    sh:property [
        sh:path aegis:ownedBy ;
        sh:nodeKind sh:IRI ;
        sh:message "camayoc: aegis:ownedBy names a principal by IRI, never a string" ;
    ] .

shapes/observation-debt.shapes.ttl:
@prefix aegis: <http://aegis.gastown.local/ontology/> .
@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix quipu: <http://quipu.dev/ontology/> .

# Write-validation debt for Observations (aegis-g51c C10; writer burn-down:
# aegis-51t). The four minCount constraints below were moved out of
# CamayocObservationShape (core.shapes.ttl), so that with validate_on_write ON a
# missing value is EMITTED as a shacl.violation warning instead of refusing the
# write. Every other Observation constraint still rejects in core.
#
# A file of its own, loaded as its own shape set: a quipu released before the
# literal-aware splitter (scbrown/quipu#726) misroutes reject shapes that share
# a file with an emit block, so core.shapes.ttl carries no emit block at all.
# The severity is on each property shape: a result takes the severity of the
# shape that produced it, and here that is the property shape.

aegis:CamayocObservationProvenanceDebtShape a sh:NodeShape ;
    quipu:onViolation "emit" ;
    sh:severity sh:Warning ;
    sh:targetClass aegis:Observation ;
    sh:property [ sh:path aegis:sourceKind ; sh:minCount 1 ; sh:severity sh:Warning ] ;
    sh:property [ sh:path aegis:about ; sh:minCount 1 ; sh:severity sh:Warning ] ;
    sh:property [ sh:path aegis:observedAt ; sh:minCount 1 ; sh:severity sh:Warning ] ;
    sh:property [ sh:path aegis:observedValue ; sh:minCount 1 ; sh:severity sh:Warning ] .
